/// <summary>
/// Extension of createParmLine to update DSD positions before creating the parameter line.
/// Calls <c>SalesFormLetter_Invoice::updateDSDPostitions_AVA</c> for the original sales line and parmId.
/// </summary>
/// <param name="_salesLineOrig">The original sales line record.</param>
/// <param name="_tableRefId">The table reference ID.</param>
/// <param name="_inventOwnerId">The inventory owner ID.</param>
/// <param name="_mcrShipAlone">Indicates if the line should ship alone.</param>
/// <returns>True if the parameter line was created successfully; otherwise, false.</returns>
protected boolean createParmLine(Common _salesLineOrig, TradeLineRefId _tableRefId, InventOwnerId_RU _inventOwnerId, boolean _mcrShipAlone)
{
    boolean ret;

    SalesFormLetter_Invoice::updateDSDPostitions_AVA(_salesLineOrig, this.parmId());
    ret = next createParmLine(_salesLineOrig, _tableRefId, _inventOwnerId, _mcrShipAlone);
    return ret;
}
